window.ATLAS_HELP_INDEX = [
{"page": "index", "anchor": "", "title": "Overview", "heading": "Overview", "text": "This guide is for the people who use atlas-duck: users and, in server mode, admins and auditors.", "href": "/docs/en/"},
{"page": "index", "anchor": "what-is-atlas-duck", "title": "Overview", "heading": "What atlas-duck is", "text": "atlas-duck lets AI agents read Jira and Confluence Data Center and propose writes that you approve. Every action is recorded in a tamper-evident audit chain. There are two ways to run it: Desktop mode", "href": "/docs/en/#what-is-atlas-duck"},
{"page": "index", "anchor": "how-it-works", "title": "Overview", "heading": "How a request flows", "text": "An agent asks atlas-duck for something, for example to read a Jira issue or to change one. The request appears in your approvals. Nothing reaches the instance yet. You decide. You approve a write, rel", "href": "/docs/en/#how-it-works"},
{"page": "index", "anchor": "where-to-start", "title": "Overview", "heading": "Where to start", "text": "Getting started (server) covers signing in, your tokens and your first agent. Instances and tokens explains the credentials page. Agents (server) covers API keys and connected apps. Then read Approval", "href": "/docs/en/#where-to-start"},
{"page": "getting-started-server", "anchor": "", "title": "Getting started (server)", "heading": "Getting started (server)", "text": "", "href": "/docs/en/getting-started-server"},
{"page": "getting-started-server", "anchor": "sign-in", "title": "Getting started (server)", "heading": "Sign in", "text": "Open the address of atlas-duck that your organisation gave you. The page \"Sign in to atlas-duck\" asks for your username and password. These are your organisation's directory credentials (a domain logi", "href": "/docs/en/getting-started-server#sign-in"},
{"page": "getting-started-server", "anchor": "add-credentials", "title": "Getting started (server)", "heading": "Store your tokens", "text": "atlas-duck acts towards Jira and Confluence as you, with your own personal access token for each instance. The instances themselves are set up by an admin. Open \"Credentials\" in the header: If the pag", "href": "/docs/en/getting-started-server#add-credentials"},
{"page": "getting-started-server", "anchor": "connect-agent", "title": "Getting started (server)", "heading": "Connect an agent", "text": "An agent reaches atlas-duck over MCP in one of two ways: With an API key that you create under \"API keys\". A key has scopes (read, propose_write, scripts), expires after 1 to 90 days and can be revoke", "href": "/docs/en/getting-started-server#connect-agent"},
{"page": "getting-started-server", "anchor": "roles", "title": "Getting started (server)", "heading": "Roles", "text": "What you may do depends on your role, and your roles come from your directory groups when you sign in. Role What it may do User Everyone who can sign in. You own your tokens, approve your agents' writ", "href": "/docs/en/getting-started-server#roles"},
{"page": "instances-and-tokens", "anchor": "", "title": "Instances and tokens", "heading": "Instances and tokens", "text": "", "href": "/docs/en/instances-and-tokens"},
{"page": "instances-and-tokens", "anchor": "instances", "title": "Instances and tokens", "heading": "Instances", "text": "An instance is one Jira or Confluence Data Center server that atlas-duck talks to. It is known by an alias, for example the short name of the server. In server mode an admin defines the instances for", "href": "/docs/en/instances-and-tokens#instances"},
{"page": "instances-and-tokens", "anchor": "add-instance", "title": "Instances and tokens", "heading": "Add an instance", "text": "Users do not add instances in server mode. Ask your admin to add one. Before you store a token, check that the URL on the \"Credentials\" page is the server you mean.", "href": "/docs/en/instances-and-tokens#add-instance"},
{"page": "instances-and-tokens", "anchor": "tokens", "title": "Instances and tokens", "heading": "Tokens", "text": "atlas-duck always acts as you, with your own personal access token (PAT), never with a shared service account. Create the token in Jira or Confluence (Profile → Personal Access Tokens) and give it onl", "href": "/docs/en/instances-and-tokens#tokens"},
{"page": "instances-and-tokens", "anchor": "token-storage", "title": "Instances and tokens", "heading": "Where tokens are stored", "text": "Your tokens are stored on the server, encrypted at rest with the server's master key. Operators who have access to that key can decrypt every stored token, so treat the server's key material as you wo", "href": "/docs/en/instances-and-tokens#token-storage"},
{"page": "instances-and-tokens", "anchor": "credentials-page", "title": "Instances and tokens", "heading": "The credentials page", "text": "\"Credentials\" in the header lists every instance with its product, URL and token state: State Meaning No token You have not stored one. Token stored The token works. The row shows the Atlassian user,", "href": "/docs/en/instances-and-tokens#credentials-page"},
{"page": "agents-server", "anchor": "", "title": "Agents (server)", "heading": "Agents (server)", "text": "", "href": "/docs/en/agents-server"},
{"page": "agents-server", "anchor": "api-keys", "title": "Agents (server)", "heading": "API keys", "text": "An API key lets an agent reach atlas-duck over MCP on your behalf. A key never approves anything: every request of the agent still waits in your approval queue. Open \"API keys\" from the header. To cre", "href": "/docs/en/agents-server#api-keys"},
{"page": "agents-server", "anchor": "scopes", "title": "Agents (server)", "heading": "Scopes", "text": "A scope says what a key, or an app, may ask for. Pick the smallest set that the agent needs. Scope Meaning read Read data and wait for your decisions. propose_write Propose changes for your approval.", "href": "/docs/en/agents-server#scopes"},
{"page": "agents-server", "anchor": "connected-apps", "title": "Agents (server)", "heading": "Connected apps", "text": "\"Connected apps\" lists the apps that you allowed to use atlas-duck over MCP with OAuth. An app never approves anything either. The table shows the App, \"Returns to\" (the address that the app returns t", "href": "/docs/en/agents-server#connected-apps"},
{"page": "agents-server", "anchor": "oauth-consent", "title": "Agents (server)", "heading": "Authorising an app", "text": "When you add atlas-duck to an MCP client that supports OAuth, the client opens your browser on the page \"Allow an app to use atlas-duck?\". Sign in first if atlas-duck asks. The page shows: the name of", "href": "/docs/en/agents-server#oauth-consent"},
{"page": "agents-server", "anchor": "mcp-endpoint", "title": "Agents (server)", "heading": "The MCP endpoint", "text": "The MCP endpoint of the server is its public address followed by /mcp, for example https://atlas-duck.example.org/mcp. Your administrator tells you the address. An agent or an app connects to it as a", "href": "/docs/en/agents-server#mcp-endpoint"},
{"page": "approvals", "anchor": "", "title": "Approvals", "heading": "Approvals", "text": "", "href": "/docs/en/approvals"},
{"page": "approvals", "anchor": "queue", "title": "Approvals", "heading": "The approval queue", "text": "Nothing an agent asks for leaves atlas-duck without your decision. Every request that needs one waits in the queue under \"Pending approvals\". When nothing waits, the list says \"No pending requests\". A", "href": "/docs/en/approvals#queue"},
{"page": "approvals", "anchor": "reading-a-request", "title": "Approvals", "heading": "Reading a request", "text": "Opening a request fills the detail pane, \"Request detail\". At first the pane only offers \"Open preview\". Opening the preview is what makes a decision possible: you decide on what you have seen. The pa", "href": "/docs/en/approvals#reading-a-request"},
{"page": "approvals", "anchor": "approve-or-deny", "title": "Approvals", "heading": "Approve, release or deny", "text": "The buttons depend on the class of the request: Request Buttons What happens Write \"Approve\" atlas-duck executes the change. Read \"Release\" The data the instance returned is handed to the agent. Scrip", "href": "/docs/en/approvals#approve-or-deny"},
{"page": "approvals", "anchor": "edit-and-redact", "title": "Approvals", "heading": "Editing and redacting", "text": "You can change what is executed, or hold back parts of what is released. Both create a new revision of the request. atlas-duck never changes the old revision. Edit a write. \"Edit before approving\" sho", "href": "/docs/en/approvals#edit-and-redact"},
{"page": "approvals", "anchor": "batch-decisions", "title": "Approvals", "heading": "Batch decisions", "text": "When many similar requests wait, decide them together. Select the rows, or use \"select all from session\", and the \"Batch decision\" bar appears. \"Approve or release N selected\" first shows what will ha", "href": "/docs/en/approvals#batch-decisions"},
{"page": "approvals", "anchor": "needs-attention", "title": "Approvals", "heading": "Needs attention", "text": "Below the queue, \"Recently decided (24 h)\" lists what was decided in the last day. Entries under \"Needs attention\" are approved writes that did not end well: the write failed, ended with an unknown ou", "href": "/docs/en/approvals#needs-attention"},
{"page": "approvals", "anchor": "unverified-text", "title": "Approvals", "heading": "Unverified text", "text": "Everything an agent writes is untrusted: the reason, the agent name and the parameters. atlas-duck therefore marks what it could not check. \"unverified\" marks a text that was written by the agent and", "href": "/docs/en/approvals#unverified-text"},
{"page": "scripts", "anchor": "", "title": "Scripts", "heading": "Scripts", "text": "", "href": "/docs/en/scripts"},
{"page": "scripts", "anchor": "what-are-scripts", "title": "Scripts", "heading": "What scripts are", "text": "A script lets an agent do many reads in one request. It is JavaScript: the body of async function main(args, atlas). Inside, it calls read operations with atlas.\u003cproduct>.\u003cop>(params), atlas.call, pag", "href": "/docs/en/scripts#what-are-scripts"},
{"page": "scripts", "anchor": "running-scripts", "title": "Scripts", "heading": "Running scripts", "text": "An agent submits a script through the MCP endpoint with the script_run tool. The API key or the app needs the scripts scope: \"run read-only scripts in the sandbox; you approve each final result\". See", "href": "/docs/en/scripts#running-scripts"},
{"page": "scripts", "anchor": "limits", "title": "Scripts", "heading": "Limits and confinement", "text": "Every script runs under limits, so that one script cannot use up your machine or an instance. The server runs scripts with the defaults below. They are fixed; there is no setting for them on the serve", "href": "/docs/en/scripts#limits"},
{"page": "scripts", "anchor": "stopping", "title": "Scripts", "heading": "Stop a script", "text": "The server pages have no \"Kill\" button. A script ends when it finishes, when it reaches its timeout, or when its request is cancelled or expires. When its result arrives in the queue, you can deny it.", "href": "/docs/en/scripts#stopping"},
{"page": "audit", "anchor": "", "title": "Audit log", "heading": "Audit log", "text": "", "href": "/docs/en/audit"},
{"page": "audit", "anchor": "audit-log", "title": "Audit log", "heading": "What the audit log records", "text": "atlas-duck keeps a record of everything that happens around a request: that it arrived, what you saw, what you decided, what was sent to the instance and what came back, and what the agent received. T", "href": "/docs/en/audit#audit-log"},
{"page": "audit", "anchor": "verify", "title": "Audit log", "heading": "Verify the chain", "text": "Verification checks that the chain is complete and unchanged: every record belongs to its predecessor, the payloads match their fingerprints, and the log head matches the copies kept elsewhere. The se", "href": "/docs/en/audit#verify"},
{"page": "audit", "anchor": "export", "title": "Audit log", "heading": "Export the log", "text": "An export copies records of a time range, with their decrypted payloads, so that someone else can check them, for example an auditor or the compliance owner. The files are readable by anyone who can o", "href": "/docs/en/audit#export"},
{"page": "audit", "anchor": "verify-export", "title": "Audit log", "heading": "Check an export with verify-export", "text": "The recipient checks an export with the command atlas-duck verify-export. It needs no access to your computer or server, and it works offline. atlas-duck verify-export \u003cdir> --manifest-sha256 \u003chex> [-", "href": "/docs/en/audit#verify-export"},
{"page": "audit", "anchor": "retention", "title": "Audit log", "heading": "Retention and legal hold", "text": "The audit log is not kept forever. The retention period says how long records stay. On the server, the operator sets the retention period, not the individual user. This guide describes what the server", "href": "/docs/en/audit#retention"},
{"page": "audit", "anchor": "integrity-incident", "title": "Audit log", "heading": "Integrity incidents", "text": "An integrity incident means that a check found something that should not be. Possible causes range from a harmless one, such as restoring a backup, to tampering. atlas-duck cannot tell which one it is", "href": "/docs/en/audit#integrity-incident"},
{"page": "settings", "anchor": "", "title": "Settings", "heading": "Settings", "text": "In server mode there is no settings page. The choices that are yours, the language and notifications, sit in the header and on the Approvals page. Instances, keys and the rest of the deployment belong", "href": "/docs/en/settings"},
{"page": "settings", "anchor": "language", "title": "Settings", "heading": "Language", "text": "atlas-duck is available in English and German. The language applies to the windows and pages, notifications and native dialogs, and to this guide. Text that agents read, audit records, logs, the comma", "href": "/docs/en/settings#language"},
{"page": "settings", "anchor": "notifications", "title": "Settings", "heading": "Notifications and attention", "text": "On the Approvals page, choose \"Enable notifications\" to let your browser alert you when a request needs your decision. Your browser asks for permission. The page then says \"Notifications are on.\", or", "href": "/docs/en/settings#notifications"},
{"page": "admin", "anchor": "", "title": "Administration", "heading": "Administration", "text": "", "href": "/docs/en/admin"},
{"page": "admin", "anchor": "users-and-roles", "title": "Administration", "heading": "Users and roles", "text": "The server has three roles: user, admin and auditor. atlas-duck does not keep passwords or a list of roles of its own. A person signs in with their directory account, and the groups of that account de", "href": "/docs/en/admin#users-and-roles"},
{"page": "admin", "anchor": "instances-admin", "title": "Administration", "heading": "Manage instances", "text": "As an admin you define the Jira and Confluence instances for everybody. Open \"Admin\" in the header. The page \"Instances\" says: \"Every user sees these instances and enters their own token for each.\" Us", "href": "/docs/en/admin#instances-admin"},
{"page": "admin", "anchor": "maintenance", "title": "Administration", "heading": "Maintenance", "text": "Some work needs the server to stand still, for example restoring a backup. The operator switches the server into maintenance mode with admin maintenance on. While it is on, every page and request exce", "href": "/docs/en/admin#maintenance"},
{"page": "auditor", "anchor": "", "title": "Auditor", "heading": "Auditor", "text": "", "href": "/docs/en/auditor"},
{"page": "auditor", "anchor": "auditor-role", "title": "Auditor", "heading": "The auditor role", "text": "An auditor can read the audit log of any user, so that the organisation can check what agents did and who decided. The role comes from a directory group, see Users and roles. Users without it do not s", "href": "/docs/en/auditor#auditor-role"},
{"page": "auditor", "anchor": "reading-the-audit", "title": "Auditor", "heading": "Read the audit log", "text": "Open \"Auditor\" in the header. The page \"Users\" lists every user, including deactivated ones. \"Search by username\" finds a person, and \"State\" narrows the list to \"Active\" or \"Deactivated\" (\"All\" shows", "href": "/docs/en/auditor#reading-the-audit"},
{"page": "auditor", "anchor": "auditor-exports", "title": "Auditor", "heading": "Exports", "text": "An auditor can export any user's log as a tar archive, for example for the compliance owner. In the user's view, choose \"All records\" or \"From date (UTC)\" and then \"Start export\". When \"The export is", "href": "/docs/en/auditor#auditor-exports"},
{"page": "troubleshooting", "anchor": "", "title": "Troubleshooting", "heading": "Troubleshooting", "text": "", "href": "/docs/en/troubleshooting"},
{"page": "troubleshooting", "anchor": "cannot-connect", "title": "Troubleshooting", "heading": "An instance cannot be reached", "text": "Symptoms: agents get unreachable, upstream_network or upstream_unavailable; a token check says that the instance cannot be reached (pat/instance_unreachable on the server). First separate two cases. I", "href": "/docs/en/troubleshooting#cannot-connect"},
{"page": "troubleshooting", "anchor": "token-rejected", "title": "Troubleshooting", "heading": "A token is rejected", "text": "Symptoms: \"The token was refused by the instance.\", state \"needs token\", agents get needs_token. The token may be mistyped or cut off when you copied it. Paste it again. The token may have expired or", "href": "/docs/en/troubleshooting#token-rejected"},
{"page": "troubleshooting", "anchor": "nothing-happens", "title": "Troubleshooting", "heading": "A request stays pending", "text": "A request waits until you decide. It is not stuck, it waits for you. Check: Open the Approvals window and look in \"Pending approvals\". The request may wait there, perhaps below others. If nothing is l", "href": "/docs/en/troubleshooting#nothing-happens"},
{"page": "troubleshooting", "anchor": "locked", "title": "Troubleshooting", "heading": "The app is locked", "text": "Symptoms: agents get locked (exit 9); the tray shows \"Waiting for keyring\" or a locked message. This is about the desktop app. The app is locked when it cannot get the key to its audit log. The detail", "href": "/docs/en/troubleshooting#locked"},
{"page": "troubleshooting", "anchor": "audit-storage", "title": "Troubleshooting", "heading": "The audit storage is low", "text": "Symptoms: agents get audit_storage_low; a warning shows in the app and in the tray; decisions fail with an audit error. This is about the desktop app; on the server the operator watches the storage. a", "href": "/docs/en/troubleshooting#audit-storage"},
{"page": "error-reference", "anchor": "", "title": "Error reference", "heading": "Error reference", "text": "", "href": "/docs/en/error-reference"},
{"page": "error-reference", "anchor": "errors-envelope", "title": "Error reference", "heading": "Errors of the command line and agents", "text": "Every failed request of an agent carries an error object with a code, a retryable flag and a message. The code tells you what went wrong. The flag tells the agent whether sending the same request agai", "href": "/docs/en/error-reference#errors-envelope"},
{"page": "error-reference", "anchor": "err-usage", "title": "Error reference", "heading": "usage", "text": "The request was not valid: a command, an option or a combination of options that atlas-duck does not know. Nothing was queued. Exit 2, not retryable. Check the command with --help.", "href": "/docs/en/error-reference#err-usage"},
{"page": "error-reference", "anchor": "err-validation", "title": "Error reference", "heading": "validation", "text": "The request was well formed but did not pass validation, for example a missing or wrong parameter of an operation. Nothing was queued. Exit 2, not retryable. Look up the operation with ops describe \u003co", "href": "/docs/en/error-reference#err-validation"},
{"page": "error-reference", "anchor": "err-markdown-placeholders", "title": "Error reference", "heading": "markdown_placeholders", "text": "The text contains placeholders that cannot be sent as written. When an agent writes a Confluence page or comment in Markdown, atlas-duck refuses a text that still contains placeholders that it put the", "href": "/docs/en/error-reference#err-markdown-placeholders"},
{"page": "error-reference", "anchor": "err-op-unsupported-by-instance", "title": "Error reference", "heading": "op_unsupported_by_instance", "text": "This instance does not support the operation, for example because its version is too old. Exit 2, not retryable. Use another operation or another instance, or ask the administrator of the instance.", "href": "/docs/en/error-reference#err-op-unsupported-by-instance"},
{"page": "error-reference", "anchor": "err-internal", "title": "Error reference", "heading": "internal", "text": "An internal error occurred in atlas-duck, or in the server. Not retryable. Try again later. If it keeps happening, tell your administrator, and give them the request id and the time.", "href": "/docs/en/error-reference#err-internal"},
{"page": "error-reference", "anchor": "err-audit-failure", "title": "Error reference", "heading": "audit_failure", "text": "The audit log could not be written, so nothing was done. atlas-duck never acts without recording it. Exit 1. For reads and scripts the agent may try again; for writes it is not retryable, because the", "href": "/docs/en/error-reference#err-audit-failure"},
{"page": "error-reference", "anchor": "err-audit-storage-low", "title": "Error reference", "heading": "audit_storage_low", "text": "The storage for the audit log is almost full. atlas-duck refuses new requests so that the log can always be written. Nothing was queued. Exit 1, retryable. Free disk space on the drive that holds the", "href": "/docs/en/error-reference#err-audit-storage-low"},
{"page": "error-reference", "anchor": "err-busy", "title": "Error reference", "heading": "busy", "text": "Another operation is running. Nothing was queued. Exit 11, retryable. Wait for the time that retry_after_s names and try again.", "href": "/docs/en/error-reference#err-busy"},
{"page": "error-reference", "anchor": "err-unreachable", "title": "Error reference", "heading": "unreachable", "text": "The command line could not reach the app, so nothing was queued. Exit 5. The details.reason says why: Reason What to do not_running The app is not running. Start it. launch_timeout The app did not sta", "href": "/docs/en/error-reference#err-unreachable"},
{"page": "error-reference", "anchor": "err-server-identity", "title": "Error reference", "heading": "server_identity", "text": "The program that answered is not the app that belongs to your user. atlas-duck refuses to talk to it. Exit 5, not retryable. This is a safety check. Make sure that no other program uses the app's conn", "href": "/docs/en/error-reference#err-server-identity"},
{"page": "error-reference", "anchor": "err-protocol-mismatch", "title": "Error reference", "heading": "protocol_mismatch", "text": "The command line and the app speak versions of the protocol that do not fit. Exit 5. Update both to the same version and restart the app. Restart the MCP server of the agent as well.", "href": "/docs/en/error-reference#err-protocol-mismatch"},
{"page": "error-reference", "anchor": "err-upstream-http", "title": "Error reference", "heading": "upstream_http", "text": "The Jira or Confluence server answered with an error. This code appears when a write failed after you approved it, when you released the error of a read, or when you denied a request and attached the", "href": "/docs/en/error-reference#err-upstream-http"},
{"page": "error-reference", "anchor": "err-upstream-network", "title": "Error reference", "heading": "upstream_network", "text": "The connection to the instance failed. Exit 6. When it happened before the request was sent, it is retryable. When it came out of a read and you released it, it is a fixed message without data and not", "href": "/docs/en/error-reference#err-upstream-network"},
{"page": "error-reference", "anchor": "err-upstream-unavailable", "title": "Error reference", "heading": "upstream_unavailable", "text": "The instance is not available right now. Exit 6. Reads can be retried later. If the reason is identity_header_missing or identity_header_mismatch, a proxy in front of Jira changes the user header, so", "href": "/docs/en/error-reference#err-upstream-unavailable"},
{"page": "error-reference", "anchor": "err-upstream-unknown-outcome", "title": "Error reference", "heading": "upstream_unknown_outcome", "text": "A write was sent, but atlas-duck does not know whether the instance carried it out, for example after a timeout, a server error or a crash. Status outcome_unknown, exit 6, not retryable. Check the tar", "href": "/docs/en/error-reference#err-upstream-unknown-outcome"},
{"page": "error-reference", "anchor": "err-result-too-large", "title": "Error reference", "heading": "result_too_large", "text": "The result is too large to return. Exit 6, not retryable. The agent should ask for less: a smaller page, fewer fields, or a narrower search.", "href": "/docs/en/error-reference#err-result-too-large"},
{"page": "error-reference", "anchor": "err-needs-token", "title": "Error reference", "heading": "needs_token", "text": "A token is needed for this instance. The token is missing, or the instance has refused it. Exit 9. Add or replace the token, see Instances and tokens and A token is rejected. Agents should not retry i", "href": "/docs/en/error-reference#err-needs-token"},
{"page": "error-reference", "anchor": "err-locked", "title": "Error reference", "heading": "locked", "text": "The app is locked: it cannot open its audit log or its keys. Exit 9. The details.reason says why, for example that the keychain is not available yet, that it was lost, or that the keyring lies on a ne", "href": "/docs/en/error-reference#err-locked"},
{"page": "error-reference", "anchor": "err-not-configured", "title": "Error reference", "heading": "not_configured", "text": "This instance, or the app, is not set up yet. Exit 9. The details.reason names the gap: the first-run wizard is not finished, no instance exists for the product, an instance uses http:// instead of ht", "href": "/docs/en/error-reference#err-not-configured"},
{"page": "error-reference", "anchor": "err-script-syntax", "title": "Error reference", "heading": "script_syntax", "text": "The script has a syntax error. atlas-duck compiles every script on submission and refuses a faulty one. Exit 8, not retryable. Fix the script. See Scripts.", "href": "/docs/en/error-reference#err-script-syntax"},
{"page": "error-reference", "anchor": "err-script-limit", "title": "Error reference", "heading": "script_limit", "text": "The script hit a limit and was stopped: time, memory, number of calls, data fetched or size of the result. Exit 8, not retryable. Make the script do less, or raise the limit in Settings, see Limits an", "href": "/docs/en/error-reference#err-script-limit"},
{"page": "error-reference", "anchor": "err-sandbox-unavailable", "title": "Error reference", "heading": "sandbox_unavailable", "text": "The script sandbox is not available, so scripts cannot run. Exit 8, not retryable. If the reason is app_upgraded, restart the app and try again. Otherwise the operating system does not allow the confi", "href": "/docs/en/error-reference#err-sandbox-unavailable"},
{"page": "error-reference", "anchor": "err-result-evicted", "title": "Error reference", "heading": "result_evicted", "text": "The outcome is known, but the result is no longer stored. Exit 10. For reads and scripts the agent can submit the request again; for a write do not repeat it, because the change was already made.", "href": "/docs/en/error-reference#err-result-evicted"},
{"page": "error-reference", "anchor": "err-denied", "title": "Error reference", "heading": "denied", "text": "You denied the request. The message holds your reason. Exit 3, not retryable. The agent should resubmit only when the reason asks for a change. See Approve, release or deny.", "href": "/docs/en/error-reference#err-denied"},
{"page": "error-reference", "anchor": "err-resolution-failed", "title": "Error reference", "heading": "resolution_failed", "text": "A name in the request could not be resolved, for example a user, a field or a project that does not exist under that name. Exit 3 when you attached it as a hint to a deny. The details name the paramet", "href": "/docs/en/error-reference#err-resolution-failed"},
{"page": "error-reference", "anchor": "err-expired", "title": "Error reference", "heading": "expired", "text": "Nobody decided the request in time. Exit 7, not retryable. Submit again only if you want that.", "href": "/docs/en/error-reference#err-expired"},
{"page": "error-reference", "anchor": "err-cancelled", "title": "Error reference", "heading": "cancelled", "text": "The request was cancelled: by the agent (cancel, not retryable), because the app was quit or the system shut down (retryable). Exit 7. Nothing was executed, and a cancelled result never reaches your q", "href": "/docs/en/error-reference#err-cancelled"},
{"page": "error-reference", "anchor": "err-abandoned", "title": "Error reference", "heading": "abandoned", "text": "The request was still pending when the app crashed or was killed. Exit 7, retryable. Submit it again. A write that was already approved becomes outcome_unknown instead, see upstream_unknown_outcome.", "href": "/docs/en/error-reference#err-abandoned"},
{"page": "error-reference", "anchor": "err-unknown-request", "title": "Error reference", "heading": "unknown_request", "text": "There is no request with this id. Exit 2. Check the id, or find it with requests list.", "href": "/docs/en/error-reference#err-unknown-request"},
{"page": "error-reference", "anchor": "err-protocol-error", "title": "Error reference", "heading": "protocol_error", "text": "The app and the command line tool could not agree on a message. Exit 1, not retryable. This usually means that they have different versions. Update both and restart the app.", "href": "/docs/en/error-reference#err-protocol-error"},
{"page": "error-reference", "anchor": "errors-decision", "title": "Error reference", "heading": "Errors when deciding", "text": "These errors appear in the Approvals window when a decision cannot be applied. In every case nothing was decided, and the request is as it was.", "href": "/docs/en/error-reference#errors-decision"},
{"page": "error-reference", "anchor": "err-stale", "title": "Error reference", "heading": "stale", "text": "The request changed in the meantime, for example it received a new revision. Re-read the queue, open the request again and decide on what you see.", "href": "/docs/en/error-reference#err-stale"},
{"page": "error-reference", "anchor": "err-invalid", "title": "Error reference", "heading": "invalid", "text": "The decision is not allowed for this request, for example approving something that cannot be approved, or releasing with a preview that you have not opened. Open the preview first, or decide individua", "href": "/docs/en/error-reference#err-invalid"},
{"page": "error-reference", "anchor": "err-edit-rejected", "title": "Error reference", "heading": "edit_rejected", "text": "The edit was refused, for example because it changes the target, is not valid, or is too large. The message names the reason. Correct the field, or deny the request. See Editing and redacting.", "href": "/docs/en/error-reference#err-edit-rejected"},
{"page": "error-reference", "anchor": "err-audit", "title": "Error reference", "heading": "audit", "text": "The decision could not be recorded in the audit log, so nothing was done. Check the free space of the audit log, then try again. See The audit storage is low.", "href": "/docs/en/error-reference#err-audit"},
{"page": "error-reference", "anchor": "err-batch-rejected", "title": "Error reference", "heading": "batch_rejected", "text": "The batch was rejected and nothing was decided. At least one request did not qualify. The reasons are listed per request, see below and Batch decisions.", "href": "/docs/en/error-reference#err-batch-rejected"},
{"page": "error-reference", "anchor": "err-not-decidable", "title": "Error reference", "heading": "not_decidable", "text": "The request is not waiting for a decision. Someone else decided it, it expired, or it was cancelled. Re-read the queue.", "href": "/docs/en/error-reference#err-not-decidable"},
{"page": "error-reference", "anchor": "errors-batch", "title": "Error reference", "heading": "Errors in batch decisions", "text": "A batch lists these reasons per request. Remove the request from the batch or decide it individually.", "href": "/docs/en/error-reference#errors-batch"},
{"page": "error-reference", "anchor": "err-not-pending", "title": "Error reference", "heading": "not_pending", "text": "The request is no longer pending. It was decided, expired or cancelled in the meantime.", "href": "/docs/en/error-reference#err-not-pending"},
{"page": "error-reference", "anchor": "err-target-param-edit", "title": "Error reference", "heading": "target_param_edit", "text": "The target of the request cannot be edited. Decide it individually, or deny it so that the agent asks again with the right target.", "href": "/docs/en/error-reference#err-target-param-edit"},
{"page": "error-reference", "anchor": "err-not-opened", "title": "Error reference", "heading": "not_opened", "text": "The preview of the request was not opened. Open the preview of every selected request before you decide as a batch.", "href": "/docs/en/error-reference#err-not-opened"},
{"page": "error-reference", "anchor": "err-not-approvable", "title": "Error reference", "heading": "not_approvable", "text": "The request cannot be approved as it is, for example because required fields are missing. Decide it individually.", "href": "/docs/en/error-reference#err-not-approvable"},
{"page": "error-reference", "anchor": "err-batch-item-flagged", "title": "Error reference", "heading": "batch_item_flagged", "text": "The request is flagged as a possible duplicate or as a similar request. Look at it and approve it individually.", "href": "/docs/en/error-reference#err-batch-item-flagged"},
{"page": "error-reference", "anchor": "errors-cmd", "title": "Error reference", "heading": "Errors of the server commands", "text": "The server pages send commands to the server. These errors come back when a command fails. The error internal is described above.", "href": "/docs/en/error-reference#errors-cmd"},
{"page": "error-reference", "anchor": "err-invalid-argument", "title": "Error reference", "heading": "invalid_argument", "text": "The request contains an invalid value. Check what you entered and try again.", "href": "/docs/en/error-reference#err-invalid-argument"},
{"page": "error-reference", "anchor": "err-not-found", "title": "Error reference", "heading": "not_found", "text": "The request, or the thing that it names, does not exist any more. Reload the page.", "href": "/docs/en/error-reference#err-not-found"},
{"page": "error-reference", "anchor": "err-release-blocked", "title": "Error reference", "heading": "release_blocked", "text": "This request cannot be released. The redactions that you made, or the data itself, would let through something that should have been held back. The page names the reason. See \"When a release is blocke", "href": "/docs/en/error-reference#err-release-blocked"},
{"page": "error-reference", "anchor": "err-unknown-command", "title": "Error reference", "heading": "unknown_command", "text": "The server does not know this command. The page and the server are of different versions. Reload the page; if it persists, tell your administrator.", "href": "/docs/en/error-reference#err-unknown-command"},
{"page": "error-reference", "anchor": "err-not-ready", "title": "Error reference", "heading": "not_ready", "text": "Your store is not ready yet, for example right after a restart. Try again in a moment.", "href": "/docs/en/error-reference#err-not-ready"},
{"page": "error-reference", "anchor": "err-audit-unreadable", "title": "Error reference", "heading": "audit_unreadable", "text": "An audit entry could not be read. The rest of the log is not affected. If it keeps happening, tell your administrator.", "href": "/docs/en/error-reference#err-audit-unreadable"},
{"page": "error-reference", "anchor": "err-audit-failed", "title": "Error reference", "heading": "audit_failed", "text": "The audit log could not be read. Try again later. If it persists, tell your administrator.", "href": "/docs/en/error-reference#err-audit-failed"},
{"page": "error-reference", "anchor": "errors-server", "title": "Error reference", "heading": "Errors of the server API", "text": "The server answers errors with an HTTP status and a code. The web pages translate the code into a message. The code is useful when you talk to your administrator.", "href": "/docs/en/error-reference#errors-server"},
{"page": "error-reference", "anchor": "err-auth-invalid-credentials", "title": "Error reference", "heading": "auth/invalid_credentials", "text": "HTTP 401. The username or password is wrong. Sign in again with your directory account.", "href": "/docs/en/error-reference#err-auth-invalid-credentials"},
{"page": "error-reference", "anchor": "err-auth-empty-password", "title": "Error reference", "heading": "auth/empty_password", "text": "HTTP 400. You did not enter a password.", "href": "/docs/en/error-reference#err-auth-empty-password"},
{"page": "error-reference", "anchor": "err-auth-directory-unavailable", "title": "Error reference", "heading": "auth/directory_unavailable", "text": "HTTP 503. The server cannot reach the directory that checks your password. People who are signed in can keep working. Try again later, or tell your administrator.", "href": "/docs/en/error-reference#err-auth-directory-unavailable"},
{"page": "error-reference", "anchor": "err-auth-not-permitted", "title": "Error reference", "heading": "auth/not_permitted", "text": "HTTP 403. This account may not use atlas-duck: it belongs to none of the groups that the server admits, or it was deactivated. Ask your administrator, see Users and roles.", "href": "/docs/en/error-reference#err-auth-not-permitted"},
{"page": "error-reference", "anchor": "err-auth-no-session", "title": "Error reference", "heading": "auth/no_session", "text": "HTTP 401. You are not signed in. Sign in first.", "href": "/docs/en/error-reference#err-auth-no-session"},
{"page": "error-reference", "anchor": "err-auth-session-expired", "title": "Error reference", "heading": "auth/session_expired", "text": "HTTP 401. The session expired. Sign in again.", "href": "/docs/en/error-reference#err-auth-session-expired"},
{"page": "error-reference", "anchor": "err-auth-csrf-mismatch", "title": "Error reference", "heading": "auth/csrf_mismatch", "text": "HTTP 403. The request token does not match your session, for example because the page was open for a long time or in two sessions. Reload the page.", "href": "/docs/en/error-reference#err-auth-csrf-mismatch"},
{"page": "error-reference", "anchor": "err-auth-origin-mismatch", "title": "Error reference", "heading": "auth/origin_mismatch", "text": "HTTP 403. The request comes from another origin than the server's own address. Use the address that your administrator gave you, and do not call the server from another website.", "href": "/docs/en/error-reference#err-auth-origin-mismatch"},
{"page": "error-reference", "anchor": "err-auth-role-required", "title": "Error reference", "heading": "auth/role_required", "text": "HTTP 403. The page or action needs a role that your account does not have, such as admin or auditor. See Users and roles.", "href": "/docs/en/error-reference#err-auth-role-required"},
{"page": "error-reference", "anchor": "err-auth-bearer-not-accepted", "title": "Error reference", "heading": "auth/bearer_not_accepted", "text": "HTTP 403. API keys and OAuth tokens cannot be used here. Only the MCP endpoint accepts them; decisions can only be made by a person who is signed in. See The MCP endpoint.", "href": "/docs/en/error-reference#err-auth-bearer-not-accepted"},
{"page": "error-reference", "anchor": "err-auth-api-key-invalid", "title": "Error reference", "heading": "auth/api_key_invalid", "text": "HTTP 401. The API key or token is not valid: it is mistyped, revoked or expired, or its user was deactivated. Create a new key, see API keys.", "href": "/docs/en/error-reference#err-auth-api-key-invalid"},
{"page": "error-reference", "anchor": "err-auth-scope-missing", "title": "Error reference", "heading": "auth/scope_missing", "text": "HTTP 403. The key lacks the scope that this needs. Create a key with the scope, see Scopes.", "href": "/docs/en/error-reference#err-auth-scope-missing"},
{"page": "error-reference", "anchor": "err-api-bad-request", "title": "Error reference", "heading": "api/bad_request", "text": "HTTP 400. The request is malformed. If you use the web pages, reload them. If an own program sends it, check the body.", "href": "/docs/en/error-reference#err-api-bad-request"},
{"page": "error-reference", "anchor": "err-api-not-found", "title": "Error reference", "heading": "api/not_found", "text": "HTTP 404. Not found. The address or the object does not exist.", "href": "/docs/en/error-reference#err-api-not-found"},
{"page": "error-reference", "anchor": "err-api-unknown-command", "title": "Error reference", "heading": "api/unknown_command", "text": "HTTP 404. The server does not know this command. Reload the page; the page and the server may be of different versions.", "href": "/docs/en/error-reference#err-api-unknown-command"},
{"page": "error-reference", "anchor": "err-api-body-too-large", "title": "Error reference", "heading": "api/body_too_large", "text": "HTTP 413. The request body is too large. Send less data.", "href": "/docs/en/error-reference#err-api-body-too-large"},
{"page": "error-reference", "anchor": "err-api-too-many-streams", "title": "Error reference", "heading": "api/too_many_streams", "text": "HTTP 429. You have too many pages open that wait for live updates. Close some tabs.", "href": "/docs/en/error-reference#err-api-too-many-streams"},
{"page": "error-reference", "anchor": "err-instance-invalid", "title": "Error reference", "heading": "instance/invalid", "text": "HTTP 400. The instance is not valid. Check the alias (letters, digits, - and _), the product, an https:// base URL and the proxy, and that the product has only one default. See Manage instances.", "href": "/docs/en/error-reference#err-instance-invalid"},
{"page": "error-reference", "anchor": "err-instance-exists", "title": "Error reference", "heading": "instance/exists", "text": "HTTP 409. An instance with this alias exists already. Choose another alias.", "href": "/docs/en/error-reference#err-instance-exists"},
{"page": "error-reference", "anchor": "err-instance-unknown", "title": "Error reference", "heading": "instance/unknown", "text": "HTTP 404. No instance has this alias, perhaps because an administrator removed it. Reload the page.", "href": "/docs/en/error-reference#err-instance-unknown"},
{"page": "error-reference", "anchor": "err-pat-check-failed", "title": "Error reference", "heading": "pat/check_failed", "text": "HTTP 422. The instance refused the token. Check that you copied it completely and that it has not expired or been revoked. See A token is rejected.", "href": "/docs/en/error-reference#err-pat-check-failed"},
{"page": "error-reference", "anchor": "err-pat-instance-unreachable", "title": "Error reference", "heading": "pat/instance_unreachable", "text": "HTTP 502. The server cannot reach the instance to check the token. Try again later, or ask your administrator. See An instance cannot be reached.", "href": "/docs/en/error-reference#err-pat-instance-unreachable"},
{"page": "error-reference", "anchor": "err-api-key-limit-reached", "title": "Error reference", "heading": "api_key/limit_reached", "text": "HTTP 409. You have the maximum of 25 active keys. Revoke one first, see API keys.", "href": "/docs/en/error-reference#err-api-key-limit-reached"},
{"page": "error-reference", "anchor": "err-api-key-expiry-out-of-range", "title": "Error reference", "heading": "api_key/expiry_out_of_range", "text": "HTTP 400. The expiry must be a whole number of days from 1 to 90.", "href": "/docs/en/error-reference#err-api-key-expiry-out-of-range"},
{"page": "error-reference", "anchor": "err-api-key-name-invalid", "title": "Error reference", "heading": "api_key/name_invalid", "text": "HTTP 400. The name must be 1 to 64 characters long and contain no control characters.", "href": "/docs/en/error-reference#err-api-key-name-invalid"},
{"page": "error-reference", "anchor": "err-api-key-scope-invalid", "title": "Error reference", "heading": "api_key/scope_invalid", "text": "HTTP 400. Choose at least one scope, and only known ones.", "href": "/docs/en/error-reference#err-api-key-scope-invalid"},
{"page": "error-reference", "anchor": "err-store-unavailable", "title": "Error reference", "heading": "store/unavailable", "text": "HTTP 503. The store is not available. Try again in a moment. If it persists, tell your administrator.", "href": "/docs/en/error-reference#err-store-unavailable"},
{"page": "error-reference", "anchor": "err-oauth-disabled", "title": "Error reference", "heading": "oauth/disabled", "text": "HTTP 404. OAuth is not enabled on this server. Use an API key instead, see API keys.", "href": "/docs/en/error-reference#err-oauth-disabled"},
{"page": "error-reference", "anchor": "err-oauth-request-unknown", "title": "Error reference", "heading": "oauth/request_unknown", "text": "HTTP 404. This authorization request is unknown. It may have been answered already, or it belongs to another session. Start again from the app, see Authorising an app.", "href": "/docs/en/error-reference#err-oauth-request-unknown"},
{"page": "error-reference", "anchor": "err-oauth-request-expired", "title": "Error reference", "heading": "oauth/request_expired", "text": "HTTP 410. This authorization request expired. Start again from the app.", "href": "/docs/en/error-reference#err-oauth-request-expired"},
{"page": "error-reference", "anchor": "err-oauth-grant-unknown", "title": "Error reference", "heading": "oauth/grant_unknown", "text": "HTTP 404. There is no such connected app. It may be revoked already. Reload \"Connected apps\".", "href": "/docs/en/error-reference#err-oauth-grant-unknown"},
{"page": "error-reference", "anchor": "err-audit-user-unknown", "title": "Error reference", "heading": "audit/user_unknown", "text": "HTTP 404. No such user has an audit log. Go back to the list of users.", "href": "/docs/en/error-reference#err-audit-user-unknown"},
{"page": "error-reference", "anchor": "err-audit-read-not-recorded", "title": "Error reference", "heading": "audit/read_not_recorded", "text": "HTTP 503. The read could not be recorded, so nothing was read. Auditing is itself audited, and the server refuses to show data that it cannot record. Try again later. See The auditor role.", "href": "/docs/en/error-reference#err-audit-read-not-recorded"},
{"page": "error-reference", "anchor": "err-audit-export-busy", "title": "Error reference", "heading": "audit/export_busy", "text": "HTTP 409. An export of this log is already running, or the server runs its maximum number of exports. Try again when it has finished.", "href": "/docs/en/error-reference#err-audit-export-busy"},
{"page": "error-reference", "anchor": "err-audit-export-unknown", "title": "Error reference", "heading": "audit/export_unknown", "text": "HTTP 404. There is no such export, or it belongs to someone else.", "href": "/docs/en/error-reference#err-audit-export-unknown"},
{"page": "error-reference", "anchor": "err-audit-export-expired", "title": "Error reference", "heading": "audit/export_expired", "text": "HTTP 410. The export is no longer available: it expired or was already downloaded. Start a new one, see Export the log.", "href": "/docs/en/error-reference#err-audit-export-expired"},
{"page": "error-reference", "anchor": "err-audit-export-failed", "title": "Error reference", "heading": "audit/export_failed", "text": "HTTP 500. The export failed. Start a new one. If it keeps failing, tell your administrator.", "href": "/docs/en/error-reference#err-audit-export-failed"},
{"page": "error-reference", "anchor": "err-server-maintenance", "title": "Error reference", "heading": "server/maintenance", "text": "HTTP 503. The server is in maintenance, for example for a restore. Try again later. See Maintenance.", "href": "/docs/en/error-reference#err-server-maintenance"},
{"page": "error-reference", "anchor": "err-auth-rate-limited", "title": "Error reference", "heading": "auth/rate_limited", "text": "HTTP 429. Too many failed sign-ins. Wait for the time that the Retry-After header names, then try again.", "href": "/docs/en/error-reference#err-auth-rate-limited"}
];
